// Simplified Extract Question & Language
const items = $input.all();

// Try to get from first item directly (most common case)
let question = $input.first().json.question || $input.first().json.queryQuestion || '';
let language = $input.first().json.language || 'English';
let deviceType = $input.first().json.deviceType || 'NA';
let browser = $input.first().json.browser || 'NA';
let latitude = $input.first().json.latitude || 'NA';
let longitude = $input.first().json.longitude || 'NA';
let fullPrompt = $input.first().json.fullPrompt || question; // ADD THIS LINE
let queryType = $input.first().json.queryType || 'NA'; // ADD THIS LINE
let mobNo = $input.first().json.mobNo || 'NA'; // ADD THIS LINE
let hasContext = $input.first().json.hasContext || false;


console.log('Direct access - Question:', question);
console.log('Direct access - fullPrompt:', fullPrompt);
console.log('Direct access - hasContext:', hasContext);

// If not found, search through all items
if (!question) {
    for (const item of items) {
        if (item.json.question) {
            question = item.json.question;
            language = item.json.language || 'English';
            deviceType = item.json.deviceType || 'NA';
            browser = item.json.browser || 'NA';
            latitude = item.json.latitude || 'NA';
            longitude = item.json.longitude || 'NA';
            fullPrompt = item.json.fullPrompt || question; // ADD THIS LINE
            queryType = item.json.queryType || 'NA'; // ADD THIS LINE
            mobNo = item.json.mobNo || 'NA'; // ADD THIS LINE
            hasContext = item.json.hasContext || false;
            console.log('Found in items array');
            break;
        }

        // Check body (webhook)
        if (item.json.body?.question) {
            question = item.json.body.question;
            language = item.json.body.language || 'English';
            deviceType = item.json.body.deviceType || 'NA';
            browser = item.json.body.browser || 'NA';
            latitude = item.json.body.latitude || 'NA';
            longitude = item.json.body.longitude || 'NA';
            fullPrompt = item.json.body.fullPrompt || question; // ADD THIS LINE
            queryType = item.json.body.queryType || 'NA'; // ADD THIS LINE
            hasContext = item.json.body.hasContext || false;
            mobNo = item.json.body.mobNo || 'NA'; // ADD THIS LINE
            console.log('Found in body');
            break;
        }
    }
}

return [{
    json: {
        question: question || 'Error: No question found',
        language: language,
        deviceType: deviceType,
        browser: browser,
        latitude: latitude,
        longitude: longitude,
        fullPrompt: fullPrompt, // ADD THIS LINE
        queryType: queryType, // ADD THIS LINE
        mobNo: mobNo, // ADD THIS LINE
        hasContext: hasContext
    }
}];

// Get user's question from previous node (Merge output)
const previousNode = $input.first();
const webhookData = previousNode.json;

// Extract data with proper fallbacks
const userQuestion = webhookData.question;
const userLanguage = webhookData.language || 'English';
const fullPrompt = webhookData.fullPrompt || userQuestion; // ⚠️ CRITICAL: Use existing fullPrompt
const latitude = webhookData.latitude;
const longitude = webhookData.longitude;
const deviceType = webhookData.deviceType;
const browser = webhookData.browser;
const queryType = webhookData.queryType;
const mobNo = webhookData.mobNo;
const hasContext = webhookData.hasContext || false;
const historyCount = webhookData.historyCount || 0;

console.log('=== SEARCH CACHE DEBUG ===');
console.log('Question:', userQuestion);
console.log('Full Prompt (first 200 chars):', fullPrompt ? fullPrompt.substring(0, 200) : 'NONE');
console.log('Has Context:', hasContext);
console.log('History Count:', historyCount);

// Get all logs from Google Sheets
const allLogs = $input.all().filter(item => item.json.Timestamp); // Only actual sheet data

// Validate input
if (!userQuestion) {
    return [{
        json: {
            cached: false,
            needsAI: true,
            error: "No question provided",
            question: "",
            language: userLanguage,
            fullPrompt: fullPrompt,
            latitude: latitude,
            longitude: longitude,
            deviceType: deviceType,
            browser: browser,
            queryType: queryType,
            mobNo: mobNo,
            hasContext: hasContext,
            historyCount: historyCount
        }
    }];
}

// **Handle empty Google Sheets response**
if (!allLogs || allLogs.length === 0) {
    console.log('⚠️ No cached data found');
    return [{
        json: {
            question: userQuestion,
            cached: false,
            needsAI: true,
            similarQuestions: [],
            contextForAI: '',
            language: userLanguage,
            totalSimilarFound: 0,
            message: "No cached data found, proceeding with AI",
            // Pass through ALL metadata - PRESERVE fullPrompt
            latitude: latitude,
            longitude: longitude,
            deviceType: deviceType,
            browser: browser,
            queryType: queryType,
            mobNo: mobNo,
            fullPrompt: fullPrompt, // ⚠️ KEEP ORIGINAL
            hasContext: hasContext,
            historyCount: historyCount
        }
    }];
}

// Normalize text for comparison
function normalizeText(text) {
    if (!text) return '';
    return text.toLowerCase()
        .trim()
        .replace(/[^\w\s\u0900-\u097F]/g, '') // Keep Hindi characters
        .replace(/\s+/g, ' ');
}

// Calculate similarity between two strings
function calculateSimilarity(str1, str2) {
    const words1 = str1.split(' ').filter(w => w.length > 2);
    const words2 = str2.split(' ').filter(w => w.length > 2);

    if (words1.length === 0 || words2.length === 0) return 0;

    // Count matching words
    const matchingWords = words1.filter(word => words2.includes(word));

    // Calculate similarity score
    const similarity = matchingWords.length / Math.max(words1.length, words2.length);
    return similarity;
}

const normalizedUserQuestion = normalizeText(userQuestion);

// Search through logs for similar questions
const matches = [];

for (const log of allLogs) {
    const logData = log.json;

    // Skip if no question or answer
    if (!logData.question || !logData.answer) continue;

    // Skip if language doesn't match
    if (logData.language && userLanguage && logData.language !== userLanguage) continue;

    const normalizedLogQuestion = normalizeText(logData.question);
    const similarity = calculateSimilarity(normalizedUserQuestion, normalizedLogQuestion);

    // Only consider matches > 50% similar
    if (similarity > 0.5) {
        matches.push({
            originalQuestion: logData.question,
            question: normalizedLogQuestion,
            answer: logData.answer,
            response: logData.answer,
            language: logData.language || 'English',
            similarity: similarity,
            timestamp: logData.Timestamp
        });
    }
}

// Sort by similarity (highest first)
matches.sort((a, b) => b.similarity - a.similarity);

// Check for very high match (>85% = exact/near-exact match)
const exactMatch = matches.find(m => m.similarity > 0.85);

if (exactMatch) {
    console.log('✅ EXACT MATCH FOUND:', exactMatch.similarity);
    // Return cached response immediately
    return [{
        json: {
            response: exactMatch.answer,
            answer: exactMatch.answer, // Add this for consistency
            source: 'cache',
            cached: true,
            similarity: exactMatch.similarity,
            question: userQuestion,
            language: exactMatch.language,
            success: true,
            matchedQuestion: exactMatch.originalQuestion,
            totalMatches: matches.length,
            // Pass through ALL metadata - PRESERVE fullPrompt
            latitude: latitude,
            longitude: longitude,
            deviceType: deviceType,
            browser: browser,
            queryType: queryType,
            mobNo: mobNo,
            fullPrompt: fullPrompt, // ⚠️ KEEP ORIGINAL
            hasContext: hasContext,
            historyCount: historyCount
        }
    }];
}

// No exact match - prepare context for AI
const topMatches = matches.slice(0, 5); // Top 5 similar questions

let contextForAI = '';
if (topMatches.length > 0) {
    console.log(`📋 Found ${topMatches.length} similar questions`);
    if (userLanguage === 'Hindi') {
        contextForAI = 'पिछले समान प्रश्न और उत्तर:\n\n';
    } else {
        contextForAI = 'Previous similar questions and answers:\n\n';
    }

    topMatches.forEach((match, index) => {
        contextForAI += `${index + 1}. Q: ${match.originalQuestion}\n`;
        contextForAI += `   A: ${match.answer}\n\n`;
    });
    contextForAI += '---\n\n';
}

console.log('🔄 Proceeding to AI with context');

return [{
    json: {
        question: userQuestion,
        cached: false,
        needsAI: true,
        similarQuestions: topMatches,
        contextForAI: contextForAI,
        language: userLanguage,
        totalSimilarFound: topMatches.length,
        // Pass through ALL metadata - PRESERVE fullPrompt
        latitude: latitude,
        longitude: longitude,
        deviceType: deviceType,
        browser: browser,
        queryType: queryType,
        mobNo: mobNo,
        fullPrompt: fullPrompt, // ⚠️ CRITICAL: Keep the conversation history intact
        hasContext: hasContext,
        historyCount: historyCount
    }
}];

// ═══════════════════════════════════════════════════════════════════
// NODE 1: Generate Search String
// Place this AFTER "Read_Main_File" node
// ═══════════════════════════════════════════════════════════════════

const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { error: 'No input data' } }];
}

const item = items[0].json;
const sec_code = (item.sec_code || '').toString().trim();
const chp_code = (item.Chp_Code || '').toString().trim();
const chapter_name = item.Chapter_Name || '';

// Generate search string (10 chars sec_code + 2 digit chp_code)
const sec_code_part = sec_code.substring(0, 10);
const chp_code_part = chp_code.padStart(2, '0').substring(0, 2);
const search_string = sec_code_part + chp_code_part;

console.log('═══════════════════════════════════════════');
console.log('🔍 CLOUDINARY SEARCH SETUP');
console.log('Chapter:', chapter_name);
console.log('Search string:', search_string);
console.log('═══════════════════════════════════════════');

// Return single item with search data
return [{
  json: {
    search_string: search_string,
    chapter_name: chapter_name,
    sec_code: sec_code,
    chp_code: chp_code_part,
    original_data: item
  }
}];

// Get search metadata from the first item (passed from the Merge node)
const items = $input.all();
let search_string = '';
let chapter_name = '';

// 1. Find the search string generated in the previous step
for (const item of items) {
  if (item.json.search_string) {
    search_string = item.json.search_string;
    chapter_name = item.json.chapter_name || '';
    break;
  }
}

if (!search_string) {
  return [{ json: { answer: '❌ Error: No search string found.', files_count: 0, files: [] } }];
}

// 2. Find and Parse the file list from GitHub
let fileList = [];
for (const item of items) {
    if (item.json.data && typeof item.json.data === 'string') {
        try {
            fileList = JSON.parse(item.json.data);
            break;
        } catch(e) {
            console.error("Failed to parse GitHub JSON");
        }
    } else if (Array.isArray(item.json)) {
        fileList = item.json;
        break;
    }
}

const all_matching_files = [];

// 3. Process and Filter the file list
for (const file of fileList) {
  const filename = file.Name || '';

  if (filename.includes(search_string)) {
    const year = file.Year || 'Unknown';
    const serverUrl = `http://103.87.24.58/dsofiles/${year}/Final/${filename}`;
    const fileExtension = filename.split('.').pop() || 'jpg';

    all_matching_files.push({
      year: year,
      filename: filename,
      download_url: serverUrl,
      url: serverUrl,
      format: fileExtension
    });
  }
}

// 4. Sort and Group for HTML Output
all_matching_files.sort((a, b) => b.year.localeCompare(a.year));
const filesByYear = {};
all_matching_files.forEach(file => {
  if (!filesByYear[file.year]) filesByYear[file.year] = [];
  filesByYear[file.year].push(file);
});

const sortedYears = Object.keys(filesByYear).sort().reverse();
let answer = chapter_name ? `📚 **${chapter_name}**\n` : '';
answer += `📁 ${all_matching_files.length} file(s) across ${sortedYears.length} year(s)\n\n`;

// 5. Generate Checkboxes (UNCHECKED BY DEFAULT) and Links
for (const year of sortedYears) {
  const yearFiles = filesByYear[year];

  // Much cleaner! Just the checkbox and the year value, no massive data attributes to break.
  answer += `📅 **${year}** &nbsp;&nbsp;<input type="checkbox" class="year-compare-cb" value="${year}" style="accent-color: #8b5cf6; width: 15px; height: 15px; cursor: pointer; vertical-align: middle;"> <span style="font-size: 13px; color: #4b5563; font-weight: 600;">Select to Compare</span>\n`;

  for (const file of yearFiles) {
    answer += `↳ <a href="${file.download_url}" target="_blank" style="color: blue; margin-left: 10px;">${file.filename}</a>\n`;
  }
  answer += '\n';
}

// 6. Add the Smart "Compare and Analyze" Button
if (all_matching_files.length > 0) {
  const safeChapterName = chapter_name ? chapter_name.replace(/'/g, "\\'") : '';

  // Safely encode all file data here instead of on the checkboxes
  const safeFilesByYear = JSON.stringify(filesByYear).replace(/"/g, '&quot;');

  // The JS logic that prevents JSON errors, safely routes data, and properly catches timeouts
  const btnJS = "const btn=this; const container=document.getElementById('modalAnswer'); const checkboxes=container.querySelectorAll('.year-compare-cb:checked'); if(checkboxes.length===0){alert('Please select at least one year to compare.');return;} const allFiles=JSON.parse(btn.getAttribute('data-masterfiles')); const payload={question:'" + safeChapterName + "',years:[],language:'English',filesByYear:{}}; checkboxes.forEach(cb=>{const y=cb.value; payload.years.push(y); payload.filesByYear[y]=allFiles[y];}); btn.innerHTML='⏳ Analyzing '+payload.years.length+' year(s)... This may take 1-2 mins'; btn.style.opacity='0.7'; btn.style.pointerEvents='none'; fetch('https://n8n-workflow-test.duckdns.org/webhook/haryana-comparison',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(async res=>{const text=await res.text(); try{return JSON.parse(text);}catch(e){console.error('Server Error:', text); if(!text || text.includes('504') || text.includes('502') || text.includes('Timeout')){throw new Error('Server timeout. The images took too long for Groq to analyze.');} throw new Error('Invalid server response. Try selecting fewer years.');}}).then(data=>{if(data.htmlReport){document.getElementById('modalAnswer').innerHTML=data.htmlReport;}else{alert('Analysis completed, but no report was returned.'); btn.innerHTML='📊 Compare and Analyze Selected Years'; btn.style.opacity='1'; btn.style.pointerEvents='auto';}}).catch(err=>{alert('Error during analysis: '+err.message); btn.innerHTML='📊 Compare and Analyze Selected Years'; btn.style.opacity='1'; btn.style.pointerEvents='auto';});";

  // The Button HTML
  answer += "<div style=\"background: #f8fafc; padding: 15px; border-radius: 12px; border: 1px solid #e2e8f0; margin-top: 10px;\"><p style=\"font-size: 13px; font-weight: 600; color: #475569; margin-bottom: 10px; margin-top: 0;\">Select the years above using the checkboxes, then click to analyze:</p><button class=\"btn-primary\" data-masterfiles=\"" + safeFilesByYear + "\" style=\"padding: 12px 24px; font-size: 15px; width: 100%; border-radius: 12px; display: flex; align-items: center; justify-content: center; gap: 8px; border: none; cursor: pointer; color: white; background: linear-gradient(135deg, #8b5cf6, #6366f1); box-shadow: 0 4px 12px rgba(139, 92, 246, 0.4);\" onclick=\"" + btnJS + "\">📊 Compare and Analyze Selected Years</button></div>";
}

return [{
