// ============= UTILITY FUNCTIONS =============
function escapeHtml(text) {
  return text.replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
}

// Normalize district names (handle Gurugram/Gurgaon variations)
function normalizeDistrictName(name) {
  const normalized = name.trim();
  // Common variations
  if (normalized.toLowerCase() === 'gurgaon') return 'Gurugram';
  return normalized;
}

// Detect and normalize units (cm, mm, millimeters, etc.)
function detectAndNormalizeUnit(text) {
  const cmPattern = /\b(cm|centimeter|centimetre)s?\b/i;
  const mmPattern = /\b(mm|millimeter|millimetre)s?\b/i;

  // Check if text contains cm values (look for patterns like "38.69 cm" or "Total: 38.69 cm")
  if (cmPattern.test(text) || /:\s*[\d.]+\s*cm/i.test(text)) {
    return { unit: 'mm', multiplier: 10 }; // Convert cm to mm for consistency
  }
  if (mmPattern.test(text)) return { unit: 'mm', multiplier: 1 };

  // Default based on data type
  return isRainfallData ? { unit: 'mm', multiplier: 1 } : { unit: '₹Cr', multiplier: 1 };
}

// ============= ADVANCED DATA EXTRACTION =============
function extractDistrictData(text, year) {
  const districts = {};
  const unitInfo = detectAndNormalizeUnit(text);

  // Method 1: Extract "District: Value unit" patterns (for mm format)
  const pattern1 = /(?:^|\n|\d+\.\s*)([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\s*:\s*([\d.]+)\s*(?:mm|cm)?/gm;
  let match;
  while ((match = pattern1.exec(text)) !== null) {
    const district = normalizeDistrictName(match[1].trim());
    let value = parseFloat(match[2]) * unitInfo.multiplier;

    // Validate reasonable values (after conversion to mm)
    if (!isNaN(value) && value >= 10 && value <= 20000 && 
        !['January', 'February', 'March', 'April', 'May', 'June', 
          'July', 'August', 'September', 'October', 'November', 'December', 'Total'].includes(district)) {
      districts[district] = value;
    }
  }

  // Method 2: Extract "**District**: Total: Value cm" pattern (for detailed monthly breakdowns)
  const pattern2 = /\*\*([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\*\*:[\s\S]*?Total\*\*:\s*([\d.]+)\s*cm/gi;
  while ((match = pattern2.exec(text)) !== null) {
    const district = normalizeDistrictName(match[1].trim());
    let value = parseFloat(match[2]) * unitInfo.multiplier;
    if (!isNaN(value) && value >= 10 && value <= 20000 && !districts[district]) {
      districts[district] = value;
    }
  }

  // Method 3: Numbered list format
  const pattern3 = /\d+\.\s+(?:\*\*)?([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)(?:\*\*)?\s*:\s*(?:[\s\S]*?Total\*\*?:\s*)?([\d.]+)\s*(?:mm|cm)?/gm;
  while ((match = pattern3.exec(text)) !== null) {
    const district = normalizeDistrictName(match[1].trim());
    let value = parseFloat(match[2]) * unitInfo.multiplier;
    if (!isNaN(value) && value >= 10 && value <= 20000 && !districts[district] &&
        !['January', 'February', 'March', 'April', 'May', 'June', 
          'July', 'August', 'September', 'October', 'November', 'December'].includes(district)) {
      districts[district] = value;
    }
  }

  // Method 4: Search for common district names followed by total values
  const commonDistricts = [
    'Ambala', 'Bhiwani', 'Charkhi Dadri', 'Faridabad', 'Fatehabad', 
    'Gurugram', 'Gurgaon', 'Hisar', 'Hissar', 'Jhajjar', 'Jind', 'Kaithal', 
    'Karnal', 'Kurukshetra', 'Mahendragarh', 'Nuh', 'Palwal', 
    'Panchkula', 'Panipat', 'Rewari', 'Rohtak', 'Sirsa', 'Sonipat', 
    'Yamunanagar'
  ];

  commonDistricts.forEach(districtName => {
    const normalizedName = normalizeDistrictName(districtName);
    if (!districts[normalizedName]) {
      // Look for "District: ... Total: Value" pattern
      const districtPattern = new RegExp(districtName + '[:\\s][\\s\\S]*?(?:Total|Annual Total)[:\\s*]+([\\.\\d]+)\\s*(?:cm|mm)?', 'i');
      const districtMatch = text.match(districtPattern);
      if (districtMatch) {
        let value = parseFloat(districtMatch[1]) * unitInfo.multiplier;
        if (!isNaN(value) && value >= 10 && value <= 20000) {
          districts[normalizedName] = value;
        }
      }
    }
  });

  return { districts, year, unit: 'mm' }; // Always return mm as standard unit
}

// ============= STATISTICAL ANALYSIS =============
function calcStats(values) {
  if (!values || values.length === 0) return null;

  const sorted = [...values].sort((a, b) => a - b);
  const sum = values.reduce((a, b) => a + b, 0);
  const mean = sum / values.length;

  const mid = Math.floor(sorted.length / 2);
  const median = sorted.length % 2 === 0 
    ? (sorted[mid - 1] + sorted[mid]) / 2 
    : sorted[mid];

  const variance = values.reduce((acc, v) => acc + Math.pow(v - mean, 2), 0) / values.length;
  const stdDev = Math.sqrt(variance);
  const cv = (stdDev / mean) * 100;

  const q1 = sorted[Math.floor(sorted.length * 0.25)];
  const q3 = sorted[Math.floor(sorted.length * 0.75)];
  const iqr = q3 - q1;

  // Additional research metrics
  const skewness = values.reduce((acc, v) => acc + Math.pow((v - mean) / stdDev, 3), 0) / values.length;
  const kurtosis = values.reduce((acc, v) => acc + Math.pow((v - mean) / stdDev, 4), 0) / values.length - 3;

  return {
    min: Math.min(...values),
    max: Math.max(...values),
    mean, median, stdDev, cv,
    range: Math.max(...values) - Math.min(...values),
    count: values.length,
    q1, q3, iqr, skewness, kurtosis
  };
}

// ============= RESEARCH INSIGHTS GENERATION =============
function generateResearchInsights(yearData) {
  const insights = [];

  // Filter out entries with null stats before processing
  const validData = yearData.filter(y => y && y.stats);
  if (validData.length === 0) return insights;

  if (validData.length > 1) {
    const first = validData[0];
    const last = validData[validData.length - 1];

    // Temporal trend analysis
    const meanChange = ((last.stats.mean - first.stats.mean) / first.stats.mean * 100);
    const timeSpan = yearData.length;

    insights.push({
      category: 'Temporal Dynamics',
      finding: `Mean ${dataType.toLowerCase()} ${meanChange > 0 ? 'increased' : 'decreased'} by ${Math.abs(meanChange).toFixed(1)}% over ${timeSpan} year(s)`,
      significance: Math.abs(meanChange) > 20 ? 'High' : Math.abs(meanChange) > 10 ? 'Moderate' : 'Low',
      implication: meanChange > 0 
        ? 'Indicates rising trend - warrants investigation into causal factors'
        : 'Declining trend observed - may suggest environmental or policy shifts'
    });

    // Variability analysis
    const cvChange = last.stats.cv - first.stats.cv;
    insights.push({
      category: 'Spatial Variability',
      finding: `Coefficient of variation ${cvChange > 0 ? 'increased' : 'decreased'} from ${first.stats.cv.toFixed(1)}% to ${last.stats.cv.toFixed(1)}%`,
      significance: Math.abs(cvChange) > 10 ? 'High' : Math.abs(cvChange) > 5 ? 'Moderate' : 'Low',
      implication: cvChange > 0 
        ? 'Growing disparities between districts - uneven distribution pattern'
        : 'Convergence pattern observed - more homogeneous distribution'
    });
  }

  // Distribution characteristics
  const latestYear = yearData[yearData.length - 1];
  if (latestYear.stats.skewness) {
    const skew = latestYear.stats.skewness;
    insights.push({
      category: 'Distribution Pattern',
      finding: `Distribution is ${Math.abs(skew) < 0.5 ? 'approximately symmetric' : skew > 0 ? 'positively skewed' : 'negatively skewed'} (skewness: ${skew.toFixed(2)})`,
      significance: Math.abs(skew) > 1 ? 'High' : 'Moderate',
      implication: Math.abs(skew) > 0.5 
        ? 'Non-normal distribution suggests presence of outliers or subgroups'
        : 'Normal distribution indicates balanced spatial pattern'
    });
  }

  return insights;
}

