      margin-bottom: 25px;
      display: flex;
      align-items: center;
      gap: 15px;
    }
    .analysis-content { 
      font-size: 16px; 
      line-height: 1.9; 
      color: #475569; 
    }

    .footer { 
      padding: 40px; 
      background: linear-gradient(135deg, #1e3c72 0%, #2a5298 100%); 
      color: white; 
      text-align: center;
      font-size: 14px;
    }

    @media print {
      body { background: white; padding: 0; }
      .container { box-shadow: none; }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>${icon} ${dataType} Research Analytics</h1>
      <div class="subtitle">Advanced Statistical Analysis & Temporal Dynamics</div>
      <div class="question">${escapeHtml(question)}</div>
    </div>

    <div class="metrics-bar">
      <div class="metric-card">
        <div class="metric-value">${yearData.length}</div>
        <div class="metric-label">Temporal Periods</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">${analyses.reduce((s, a) => s + a.filesCount, 0)}</div>
        <div class="metric-label">Source Documents</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">${yearData.reduce((sum, y) => sum + y.values.length, 0)}</div>
        <div class="metric-label">Data Observations</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">${commonDistricts.length > 0 ? commonDistricts.length : yearData[0]?.values.length || 0}</div>
        <div class="metric-label">${commonDistricts.length > 0 ? 'Common' : 'Total'} Districts</div>
      </div>
    </div>

    <div class="content">
      ${researchInsights.length > 0 ? `
      <h2 class="section-title">🔬 Research Insights & Implications</h2>
      <div class="insights-section">
        <h3 style="font-size: 28px; margin-bottom: 35px; font-weight: 700;">Key Findings for Academic Research</h3>
        ${researchInsights.map(insight => `
          <div class="insight-card">
            <div class="insight-category">${insight.category}</div>
            <div class="insight-finding">${insight.finding}</div>
            <span class="insight-significance">${insight.significance} Significance</span>
            <div class="insight-implication">${insight.implication}</div>
          </div>
        `).join('')}
      </div>
      ` : ''}

      ${yearData.some(y => y.stats) ? `
      <h2 class="section-title">📊 Statistical Summary & Descriptive Analytics</h2>
      ${yearData.map(y => y.stats ? `
        <div class="stats-panel">
          <h3 style="font-size: 26px; margin-bottom: 10px; font-weight: 700;">${y.year}</h3>
          <p style="opacity: 0.9; margin-bottom: 25px;">Sample size: n = ${y.values.length} districts</p>
          <div class="stats-grid">
            <div class="stat-item">
              <div class="stat-item-label">Mean (μ)</div>
              <div class="stat-item-value">${y.stats.mean.toFixed(1)} ${displayUnit}</div>
            </div>
            <div class="stat-item">
              <div class="stat-item-label">Median</div>
              <div class="stat-item-value">${y.stats.median.toFixed(1)} ${displayUnit}</div>
            </div>
            <div class="stat-item">
              <div class="stat-item-label">Std Dev (σ)</div>
              <div class="stat-item-value">${y.stats.stdDev.toFixed(1)} ${displayUnit}</div>
            </div>
            <div class="stat-item">
              <div class="stat-item-label">CV (%)</div>
              <div class="stat-item-value">${y.stats.cv.toFixed(1)}%</div>
            </div>
            <div class="stat-item">
              <div class="stat-item-label">Range</div>
              <div class="stat-item-value">${y.stats.range.toFixed(1)} ${displayUnit}</div>
            </div>
            <div class="stat-item">
              <div class="stat-item-label">IQR</div>
              <div class="stat-item-value">${y.stats.iqr.toFixed(1)} ${displayUnit}</div>
            </div>
            ${y.stats.skewness !== undefined ? `
            <div class="stat-item">
              <div class="stat-item-label">Skewness</div>
              <div class="stat-item-value">${y.stats.skewness.toFixed(2)}</div>
            </div>
            <div class="stat-item">
              <div class="stat-item-label">Kurtosis</div>
              <div class="stat-item-value">${y.stats.kurtosis.toFixed(2)}</div>
            </div>
            ` : ''}
          </div>
        </div>
      ` : '').join('')}
      ` : ''}

      <h2 class="section-title">📋 District-wise Comparative Data</h2>
      ${yearData.map((y, idx) => `
        <h3 style="font-size: 24px; margin: 30px 0 20px; color: #1e293b; font-weight: 700;">
          📅 ${y.year} - District Distribution (n=${y.values.length})
        </h3>
        <div class="data-table-wrapper">
          <table class="data-table">
            <thead>
              <tr>
                <th style="width: 60px;">Rank</th>
                <th>District Name</th>
                <th style="text-align: right;">${dataType} (${displayUnit})</th>
                <th style="text-align: right;">% of Mean</th>
                ${yearData.length > 1 && idx > 0 ? '<th style="text-align: right;">YoY Change</th>' : ''}
              </tr>
            </thead>
            <tbody>
              ${Object.entries(y.districts)
                .sort(([,a], [,b]) => b - a)
                .map(([district, value], rankIdx) => {
                  const percentOfMean = (value / y.stats.mean * 100);
                  let yoyChange = null;
                  if (idx > 0) {
                    const prevYear = yearData[idx - 1];
                    const prevValue = prevYear.districts[district];
                    if (prevValue) {
                      yoyChange = ((value - prevValue) / prevValue * 100);
                    }
                  }
                  return `
                  <tr>
                    <td style="text-align: center;">
                      ${rankIdx < 3 ? `<span class="rank-badge">#${rankIdx + 1}</span>` : `#${rankIdx + 1}`}
                    </td>
                    <td class="district-name">${district}</td>
                    <td class="value-cell" style="text-align: right;">${value.toFixed(1)}</td>
                    <td style="text-align: right; color: ${percentOfMean > 100 ? '#10b981' : '#64748b'}; font-weight: 600;">
                      ${percentOfMean.toFixed(0)}%
                    </td>
                    ${yearData.length > 1 && idx > 0 ? `
                    <td style="text-align: right;">
                      ${yoyChange !== null ? `
                        <span class="${yoyChange >= 0 ? 'change-positive' : 'change-negative'}">
                          ${yoyChange >= 0 ? '↑' : '↓'} ${Math.abs(yoyChange).toFixed(1)}%
                        </span>
                      ` : '-'}
                    </td>
                    ` : ''}
                  </tr>
                  `;
                }).join('')}
            </tbody>
          </table>
        </div>
      `).join('')}

      ${districtComparisons.length > 1 ? `
      <h3 style="font-size: 24px; margin: 40px 0 20px; color: #1e293b; font-weight: 700;">
        📈 Temporal Comparison Across All Years
      </h3>
      <div class="data-table-wrapper">
        <table class="data-table">
          <thead>
            <tr>
              <th>District</th>
              ${yearData.map(y => `<th style="text-align: right;">${y.year}</th>`).join('')}
              <th style="text-align: right;">Period Change (%)</th>
              <th style="text-align: right;">Avg Value</th>
            </tr>
          </thead>
          <tbody>
            ${districtComparisons.map(comp => `
            <tr>
              <td class="district-name">${comp.district}</td>
              ${comp.values.map(v => `<td class="value-cell" style="text-align: right;">${v.value.toFixed(1)}</td>`).join('')}
              <td style="text-align: right;">
                <span class="${comp.change >= 0 ? 'change-positive' : 'change-negative'}">
                  ${comp.change >= 0 ? '↑' : '↓'} ${Math.abs(comp.change).toFixed(1)}%
                </span>
              </td>
              <td class="value-cell" style="text-align: right;">${comp.avgValue.toFixed(1)}</td>
            </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
      ` : ''}

      <h2 class="section-title">📈 Visual Analytics & Trends</h2>
      <div class="chart-grid">
        ${yearData.length > 1 ? `
        <div class="chart-container">
          <div class="chart-title">📊 Temporal Trend Analysis</div>
          <canvas id="trendChart"></canvas>
        </div>
        ` : ''}

        <div class="chart-container">
          <div class="chart-title">📉 Statistical Distribution</div>
          <canvas id="distChart"></canvas>
        </div>

        ${districtComparisons.length > 0 && districtComparisons.length <= 15 ? `
        <div class="chart-container" style="grid-column: 1 / -1;">
          <div class="chart-title">🗺️ Top ${Math.min(10, districtComparisons.length)} Districts - Comparative Analysis</div>
          <canvas id="districtChart"></canvas>
        </div>
        ` : ''}

        ${yearData.length === 1 && yearData[0].values.length > 5 ? `
        <div class="chart-container" style="grid-column: 1 / -1;">
          <div class="chart-title">🗺️ District-wise Distribution - ${yearData[0].year}</div>
          <canvas id="singleYearChart"></canvas>
        </div>
        ` : ''}
      </div>
    </div>

    <div class="footer">
      <div style="font-size: 16px; font-weight: 600; margin-bottom: 10px;">
        🤖 Advanced Research Analytics System
      </div>
      <div style="opacity: 0.9;">
        Generated: ${new Date().toLocaleString()} | 
        Periods Analyzed: ${yearData.length} | 
        Total Observations: ${yearData.reduce((s, y) => s + y.values.length, 0)} | 
        Statistical Methods: Descriptive Statistics, Temporal Analysis, Distribution Analysis
      </div>
    </div>
  </div>

  <script>
    Chart.defaults.font.family = "'Segoe UI', system-ui, sans-serif";
    Chart.defaults.font.size = 13;

    const yearData = ${JSON.stringify(yearData.map(y => ({
      year: y.year,
      stats: y.stats,
      districts: y.districts,
      districtNames: y.districtNames
    })))};
    const distComps = ${JSON.stringify(districtComparisons.slice(0, 10))};

    // Color schemes for professional visualizations
    const colors = {
      primary: ['#1e3c72', '#2a5298', '#7e22ce', '#a855f7', '#c084fc'],
      trend: '#7e22ce',
      positive: '#10b981',
      negative: '#ef4444',
      neutral: '#64748b'
    };

    ${yearData.length > 1 ? `
    // Temporal Trend Chart
    new Chart(document.getElementById('trendChart'), {
      type: 'line',
      data: {
        labels: yearData.map(y => y.year),
        datasets: [
          {
            label: 'Mean ${dataType} (${displayUnit})',
            data: yearData.map(y => y.stats.mean),
            borderColor: colors.trend,
            backgroundColor: 'rgba(126, 34, 206, 0.1)',
            tension: 0.4,
            fill: true,
            pointRadius: 8,
            pointHoverRadius: 12,
            pointBackgroundColor: colors.trend,
            borderWidth: 3
          },
          {
            label: 'Median',
            data: yearData.map(y => y.stats.median),
            borderColor: colors.primary[1],
            backgroundColor: 'rgba(42, 82, 152, 0.1)',
            tension: 0.4,
            fill: false,
            pointRadius: 6,
            borderWidth: 2,
            borderDash: [5, 5]
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: true,
        plugins: { 
          legend: { 
            position: 'bottom',
            labels: { padding: 20, font: { size: 14, weight: '600' } }
          },
          tooltip: {
            backgroundColor: 'rgba(0,0,0,0.8)',
            padding: 15,
            titleFont: { size: 14, weight: 'bold' },
            bodyFont: { size: 13 }
          }
        },
        scales: { 
          y: { 
            beginAtZero: false,
            grid: { color: 'rgba(0,0,0,0.05)' },
            ticks: { font: { size: 12, weight: '600' } }
          },
          x: {
            grid: { display: false },
            ticks: { font: { size: 12, weight: '600' } }
          }
        }
      }
    });
    ` : ''}

    // Statistical Distribution Chart
    new Chart(document.getElementById('distChart'), {
      type: 'bar',
      data: {
        labels: yearData.map(y => y.year),
        datasets: [
          {
            label: 'Min',
            data: yearData.map(y => y.stats.min),
            backgroundColor: 'rgba(100, 116, 139, 0.6)',
            borderColor: 'rgba(100, 116, 139, 1)',
            borderWidth: 2
          }, 
          {
            label: 'Q1 (25th %ile)',
            data: yearData.map(y => y.stats.q1),
            backgroundColor: 'rgba(42, 82, 152, 0.6)',
            borderColor: 'rgba(42, 82, 152, 1)',
            borderWidth: 2
          },
          {
            label: 'Median',
            data: yearData.map(y => y.stats.median),
            backgroundColor: 'rgba(126, 34, 206, 0.8)',
            borderColor: 'rgba(126, 34, 206, 1)',
            borderWidth: 2
          },
          {
            label: 'Q3 (75th %ile)',
            data: yearData.map(y => y.stats.q3),
            backgroundColor: 'rgba(168, 85, 247, 0.6)',
            borderColor: 'rgba(168, 85, 247, 1)',
            borderWidth: 2
          }, 
          {
            label: 'Max',
            data: yearData.map(y => y.stats.max),
            backgroundColor: 'rgba(192, 132, 252, 0.6)',
            borderColor: 'rgba(192, 132, 252, 1)',
            borderWidth: 2
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: true,
        plugins: { 
          legend: { 
            position: 'bottom',
            labels: { padding: 15, font: { size: 13, weight: '600' } }
          },
          tooltip: {
            backgroundColor: 'rgba(0,0,0,0.8)',
            padding: 12
          }
        },
        scales: { 
          y: { 
            beginAtZero: false,
            grid: { color: 'rgba(0,0,0,0.05)' },
            ticks: { font: { size: 12, weight: '600' } }
          },
          x: {
            grid: { display: false },
            ticks: { font: { size: 12, weight: '600' } }
          }
        }
      }
    });

    ${districtComparisons.length > 0 && districtComparisons.length <= 15 ? `
    // Top Districts Comparison
    new Chart(document.getElementById('districtChart'), {
      type: 'bar',
      data: {
        labels: distComps.map(d => d.district),
        datasets: yearData.map((y, i) => ({
          label: y.year,
          data: distComps.map(d => {
            const val = d.values.find(v => v.year === y.year);
            return val ? val.value : 0;
          }),
          backgroundColor: colors.primary[i % colors.primary.length],
          borderWidth: 0
        }))
      },
      options: {
        responsive: true,
        maintainAspectRatio: true,
        plugins: { 
          legend: { 
            position: 'bottom',
            labels: { padding: 20, font: { size: 14, weight: '600' } }
          },
          tooltip: {
            backgroundColor: 'rgba(0,0,0,0.8)',
            padding: 15
          }
        },
        scales: { 
          y: { 
            beginAtZero: false,
            grid: { color: 'rgba(0,0,0,0.05)' },
            ticks: { font: { size: 12, weight: '600' } }
          },
          x: {
            grid: { display: false },
            ticks: { font: { size: 11, weight: '600' } }
          }
        }
      }
    });
    ` : ''}

    ${yearData.length === 1 && yearData[0].values.length > 5 ? `
    // Single Year Distribution
    const singleYearData = Object.entries(yearData[0].districts)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 15);

    new Chart(document.getElementById('singleYearChart'), {
      type: 'bar',
      data: {
        labels: singleYearData.map(([district]) => district),
        datasets: [{
          label: '${dataType} (${displayUnit})',
          data: singleYearData.map(([, value]) => value),
          backgroundColor: colors.primary[0],
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: true,
        plugins: { 
          legend: { display: false },
          tooltip: {
            backgroundColor: 'rgba(0,0,0,0.8)',
            padding: 15
          }
        },
        scales: { 
          y: { 
            beginAtZero: false,
            grid: { color: 'rgba(0,0,0,0.05)' },
            ticks: { font: { size: 12, weight: '600' } }
          },
          x: {
            grid: { display: false },
            ticks: { font: { size: 11, weight: '600' } }
          }
        }
      }
    });
    ` : ''}
  </script>
</body>
</html>`;

return {
  htmlReport: html,
  question: question,
  totalYears: yearData.length,
  dataPointsExtracted: yearData.reduce((s, y) => s + y.values.length, 0),
  yearsAnalyzed: yearData.map(y => y.year),
  researchInsights: researchInsights,
  generatedAt: new Date().toISOString()
}

// STEP 4D: COLLECT ALL FILES FOR YEAR (USING CODE NODE)
// This replaces the Aggregate node with a Code node for better control

// Get all items (all the base64-converted files for this year)
const items = $input.all();

if (!items || items.length === 0) {
  throw new Error('No files to aggregate');
}

// Extract common metadata from first item
const firstItem = items[0].json;
const year = firstItem.year;
const question = firstItem.question;
const language = firstItem.language;

// Collect all files with their base64 data
const files = items.map(item => ({
  filename: item.json.filename,
  base64: item.json.base64,
  mimeType: item.json.mimeType
}));

// Return a single item with all files
return {
  year: year,
  question: question,
  language: language,
  filesCount: files.length,
  files: files
};
